<script setup lang="ts">
import {computed,ref} from 'vue'
import {useCareerStore} from '../stores/career'
const store=useCareerStore(),form=ref({companyName:'未来科技',positionName:'Java 后端实习生',rawContent:'熟练掌握 Java 和 Spring Boot，掌握 MySQL；了解 Redis、Linux、Docker 和消息队列。具备 Git 协作经验者优先。'})
const pref=computed(()=>store.match?.preferredRate==null?'N/A':`${store.match.preferredRate}%`)
async function create(){await store.createJob(form.value)}
</script>
<template><section class="workspace-page job-layout"><div class="surface sticky-form"><p class="kicker">JOB DESCRIPTION</p><h2>录入目标岗位</h2><p class="muted">粘贴完整 JD。系统会按语义子句区分必需技能和加分项。</p><div class="field-grid"><label>公司<input v-model="form.companyName"></label><label>岗位<input v-model="form.positionName"></label><label class="wide">JD 原文<textarea v-model="form.rawContent" rows="13"></textarea></label></div><button class="button full" :disabled="store.loading" @click="create">{{store.loading?'正在分析…':'解析并计算匹配'}}</button></div><div class="match-column"><div v-if="store.match" class="surface score-panel"><div class="score-summary"><div class="score-number"><span>证据化匹配</span><b>{{store.match.score}}</b><small>/ 100</small></div><div><span class="confidence">置信度 · {{store.match.confidence}}</span><p>{{store.match.recommendation}}</p></div></div><div class="dimension-grid"><article><span>技能覆盖</span><b>{{store.match.dimensions.skillCoverage}}%</b><i :style="{width:store.match.dimensions.skillCoverage+'%'}"></i></article><article><span>证据强度</span><b>{{store.match.dimensions.evidenceStrength}}%</b><i :style="{width:store.match.dimensions.evidenceStrength+'%'}"></i></article><article><span>熟练度适配</span><b>{{store.match.dimensions.proficiencyFit}}%</b><i :style="{width:store.match.dimensions.proficiencyFit+'%'}"></i></article><article><span>项目相关性</span><b>{{store.match.dimensions.projectRelevance}}%</b><i :style="{width:store.match.dimensions.projectRelevance+'%'}"></i></article></div><div class="rate-line"><span>必需项覆盖 <b>{{store.match.requiredRate}}%</b></span><span>加分项覆盖 <b>{{pref}}</b></span></div></div><div v-if="store.match" class="requirement-list"><article v-for="item in store.match.details" :key="item.skillName" :class="item.status.toLowerCase()"><header><div><span>{{item.importance==='REQUIRED'?'必需':'加分'}}</span><h3>{{item.skillName}}</h3></div><b>{{item.status==='MATCHED'?'证据充分':item.status==='WEAK'?'证据偏弱':'尚未覆盖'}}</b></header><p>{{item.evidence}}</p><small>JD：{{item.originalText}}</small><div class="mini-scores"><i>证据 {{Math.round(item.evidenceScore*100)}}%</i><i>熟练度 {{Math.round(item.proficiencyScore*100)}}%</i><i>相关性 {{Math.round(item.relevanceScore*100)}}%</i></div></article></div><div v-else class="surface empty-state tall"><b>选择或创建一个目标岗位</b><p>系统将展示评分公式、逐项证据和置信度，不只给一个黑盒数字。</p><button v-if="store.selectedJob" class="outline-button" @click="store.calculateMatch">计算当前岗位</button></div></div></section></template>
